  length:{label:'Length',units:{m:['Meter',1],km:['Kilometer',1000],cm:['Centimeter',.01],mm:['Millimeter',.001],mi:['Mile',1609.344],yd:['Yard',.9144],ft:['Foot',.3048],in:['Inch',.0254],nmi:['Nautical mile',1852]}},
